script.source:
return ['_doc': ctx.payload.hits.hits.stream().map(
        v -> {v.get('_source').put('index', v.get('_index'));
        v.remove('_index');
        v.remove('_type');
        v.get('_source').put('threat.detection', ctx.watch_id);
        v.get('_source').put('threat.framework', 'MITRE ATT&CK');
        v.get('_source').put('threat.tactic.id', 'TA0006');
        v.get('_source').put('threat.tactic.name', 'Credential Access');
        v.get('_source').put('threat.tactic.reference', 'https://attack.mitre.org/tactics/TA0006');
        v.get('_source').put('event.timestamp_detected', ctx.trigger.triggered_time);
        v.get('_source').put('threat.is_alert', true);
        v.get('_source').put('threat.alert_type', 'AWS GuardDuty Credential Access detection');
        v.get('_source').put('threat.detection_description', 'Detection of AWS GuardDuty findings of potential credential access activity.');
        v.get('_source').put('threat.severity', 'high');
        v.get('_source').put('threat.triage_score', 60);
        v.get('_source').put('threat.ratingtime_sla_applies', 'true');
        v.get('_source').put('id', v.get('_id'));
        return v.get('_source')}).collect(Collectors.toList())]
